  text-decoration: none;
}
.logo:hover { text-decoration: none; }
.search-bar {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 8px 16px 8px 36px;
  border: 2px solid #2a2a4a;
  border-radius: 6px;
  background: #1a1a3e;
  color: #ccc;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.2s;
}
.search-bar input::placeholder { color: #888; }
.search-bar input:focus { border-color: #FEAC32; }
.search-bar .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #888;
  font-size: 0.85rem;
}
.nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}
.nav-links a {
  color: #ccc;
  font-size: 0.9rem;
  font-weight: 500;
  transition: color 0.2s;
  text-decoration: none;
}
.nav-links a:hover { color: #FEAC32; text-decoration: none; }
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 4px 8px;
}
.mobile-nav {
  display: none;
  background: #0a0a23;
  padding: 16px 24px;
  border-top: 1px solid #2a2a4a;
}
.mobile-nav.active { display: block; }
.mobile-nav a {
