  font-size: 1rem;
  border-bottom: 1px solid #1a1a3e;
  text-decoration: none;
}
.mobile-nav a:hover { color: #FEAC32; text-decoration: none; }

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: block; }
  .search-bar { max-width: 200px; }
}

/* === Banner === */
